// Generates src/generated/payload.ts from the TracePayload JSON Schema on stdin.
// Usage: <schema JSON> | node scripts/gen-types.mjs <output>; see the `gen-types` pixi task.

import { writeFileSync } from "node:fs";
import { compile } from "json-schema-to-typescript";

const BANNER = `// GENERATED by \`pixi run gen-types\` from pydantic_ai_trace.payload.TracePayload.
// Do not edit; change the Python models and regenerate.`;

/** Drop property-level titles so only named definitions become named types. */
function stripTitles(schema, isDefinition) {
  if (Array.isArray(schema)) return schema.map((item) => stripTitles(item, false));
  if (schema === null || typeof schema !== "object") return schema;
  // A `$ref` is the whole type; siblings such as `default` would make json2ts widen it.
  if (typeof schema.$ref === "string") return { $ref: schema.$ref };
  const result = {};
  for (const [key, value] of Object.entries(schema)) {
    if (key === "title" && !isDefinition) continue;
    if (key === "$defs") {
      result[key] = Object.fromEntries(
        Object.entries(value).map(([name, def]) => [name, stripTitles(def, true)]),
      );
      continue;
    }
    result[key] = stripTitles(value, false);
  }
  // Serialization always writes every field, so every property is present on the wire.
  if (result.properties) result.required = Object.keys(result.properties);
  return result;
}

let input = "";
for await (const chunk of process.stdin) input += chunk;
const schema = stripTitles(JSON.parse(input), true);
// Pydantic's `JsonValue` is an unconstrained schema; type it as `unknown`.
schema.$defs.JsonValue = { title: "JsonValue", tsType: "unknown" };
const output = await compile(schema, "TracePayload", {
  additionalProperties: false,
  bannerComment: BANNER,
  format: true,
  unreachableDefinitions: false,
});
writeFileSync(process.argv[2], output);
